  ItemWithDrawer:
    'import { Drawer, DrawerContent, DrawerDescription, DrawerHeader, DrawerTitle, DrawerTrigger } from "@/components/drawer"\nimport { Item, ItemContent, ItemDescription, ItemMedia, ItemTitle } from "@/components/item"\nimport { FileIcon, FileSearchIcon } from "lucide-react"\n\nexport function ItemWithDrawer() {\n  return (\n    <div className="flex flex-col gap-6">\n      <Drawer>\n        <Item asChild variant="outline">\n          <DrawerTrigger>\n            <ItemMedia variant="icon">\n              <FileSearchIcon />\n            </ItemMedia>\n            <ItemContent>\n              <ItemTitle>Explored 4 files</ItemTitle>\n              <ItemDescription>\n                Review the files that were searched for this answer.\n              </ItemDescription>\n            </ItemContent>\n          </DrawerTrigger>\n        </Item>\n        <DrawerContent>\n          <DrawerHeader>\n            <DrawerTitle>Explored files</DrawerTitle>\n            <DrawerDescription>\n              Files opened while generating the response.\n            </DrawerDescription>\n          </DrawerHeader>\n          <div className="grid gap-3 p-4">\n            {[\n              "app/chat/page.tsx",\n              "components/message.tsx",\n              "lib/ai.ts",\n              "app/api/chat/route.ts",\n            ].map((file) => (\n              <Item key={file} variant="muted" size="sm">\n                <ItemMedia variant="icon">\n                  <FileIcon />\n                </ItemMedia>\n                <ItemContent>\n                  <ItemTitle>{file}</ItemTitle>\n                </ItemContent>\n              </Item>\n            ))}\n          </div>\n        </DrawerContent>\n      </Drawer>\n    </div>\n  )\n}\n',
